def load_config(path):
    if not os.path.exists(path):
        return None, None
    try:
        if tomllib is None:
            return None, None
        with open(path, "rb") as f:
            data = tomllib.load(f)
        return data, None
    except Exception as e:
        return None, f"Ignoring invalid config file '{path}': couldn't parse TOML file"

