    if explicit:
        return explicit
    # check ./config.toml? Actually dust looks at ~/.config/dust/config.toml and ~/.dust.toml
    home = os.path.expanduser("~")
    cand1 = os.path.join(home, ".config", "dust", "config.toml")
    cand2 = os.path.join(home, ".dust.toml")
    for c in [cand1, cand2]:
        if os.path.exists(c):
            return c
    return None

