        if spec.startswith('+'):
            n=int(spec[1:])
            threshold=now-(n+1)*86400
            return ftime < threshold
        elif spec.startswith('-'):
            n=int(spec[1:])
            threshold=now-n*86400
            return ftime > threshold
        else:
            n=int(spec)
            low=now-(n+1)*86400
            high=now-n*86400
            return low <= ftime < high
