        if opts['filecount']:
            node.size=sum(c.size for c in children)
        elif opts['filetime']:
            ft=opts['filetime']
            if ft=='m': own=st.st_mtime
            elif ft=='a': own=st.st_atime
            elif ft=='c': own=st.st_ctime
            else: own=st.st_mtime
            if not children: node.size=own
            else: node.size=max(c.size for c in children) if children else own
        else:
            total=sum(c.size for c in children)
