def handle_ignore(node, ignore_list, root_path):
    if not ignore_list: return node
    def check(n):
        try:
            rel=os.path.relpath(n.fullpath, root_path)
            if rel=='.': rel=os.path.basename(n.fullpath)
        except:
            rel=n.name
        candidates=[rel, n.fullpath, n.path]
        for pat in ignore_list:
            pat_norm=pat.rstrip('/')
            if pat_norm in candidates:
                return True
