    if node.is_dir:
        for c in node.children:
            recompute(c, opts)
        if opts['filecount']:
            node.size=sum(c.size for c in node.children)
        elif opts['filetime']:
            if node.children:
                node.size=max(c.size for c in node.children)
        else:
            # sum children only (filtered handling)
            if node.children:
                node.size=sum(c.size for c in node.children)
            else:
                node.size=0 if not opts['filecount'] else 0

def apply_filter_prune(node, opts):
    if node.is_dir:
        new_children=[]
        for c in node.children:
            pr=apply_filter_prune(c, opts)
            if pr is not None:
                new_children.append(pr)
        node.children=new_children
        # If filter active and dir has no children after pruning, prune dir (but keep root)
        if opts['filter'] is not None or opts['invert_filter'] is not None or opts.get('invert_extra'):
