                # Determine if node's path matches filter criteria for being kept
                keep=False
                if opts['filter'] is not None:
                    try:
                        if re.search(opts['filter'], node.fullpath):
                            keep=True
                    except: pass
                if opts['invert_filter'] is not None:
                    try:
                        if not re.search(opts['invert_filter'], node.fullpath):
                            # invert means exclude matching, so if node matches invert, it was already filtered? For invert, we exclude matching paths, so node's path matching invert should be excluded earlier.
                            pass
                    except: pass
                if not keep:
                    # For filter case, prune empty dirs
                    return None
        # recompute size for dirs after pruning (sum children)
        if node.is_dir and (opts['filter'] or opts['invert_filter'] or opts.get('invert_extra')):
            if node.children:
                if opts['filecount']:
                    node.size=sum(c.size for c in node.children)
                elif opts['filetime']:
                    node.size=max(c.size for c in node.children) if node.children else 0
                else:
                    node.size=sum(c.size for c in node.children)
            else:
                node.size=0
        return node
    else:
        return node

